import { digest } from './study-version-content.mjs'

// Display IDs are regenerated by prepareLesson. Stable keys and all authored
// fields remain dependencies; an unchanged key alone is never a cache hit.
export function authored(value) {
  if (Array.isArray(value)) return value.map(authored)
  if (!value || typeof value !== 'object') return value
  return Object.fromEntries(Object.entries(value).filter(([key]) => key !== 'id' || !/-[a-f0-9]{12}-[qf]\d+$/.test(String(value.id))).map(([key,item]) => [key,authored(item)]))
}
export function questionDependencies(chapter, question) {
  const objectives = new Set(question.objectiveIds || [])
  const related = new Set((question.misconceptions || []).map(m => m.followUpKey))
  return {
    question: authored(question),
    teaching: chapter.sections.filter(s => !s.objectiveIds?.length || s.objectiveIds.some(id => objectives.has(id))),
    objectives: chapter.teachingPlan?.objectives.filter(o => objectives.has(o.id)),
    followUps: authored(chapter.questions.filter(q => related.has(q.key))),
  }
}
export function boundedReviewItems(items, maxItems = 24, maxChars = 48000) {
  const selected = []; let chars = 0
  for (const item of items) {
    const size = JSON.stringify(item).length
    if (selected.length && (selected.length >= maxItems || chars + size > maxChars)) break
    selected.push(item); chars += size
  }
  return selected
}
export const dependencyHash = value => digest(authored(value))
